/* ============================================
   RedRoom Fitness — Global Styles
   ============================================ */

/* CSS Variables */
:root {
  --bg: #141414;
  --bg-elevated: #1a1a1a;
  --bg-card: #1e1e1e;
  --red: #FF0000;
  --red-dark: #cc0000;
  --text: #FFFFFF;
  --text-muted: #a0a0a0;
  --border: #2a2a2a;
  --font-headline: 'Oswald', 'Bebas Neue', Impact, sans-serif;
  --font-body: 'Inter', 'Helvetica Neue', Helvetica, Arial, sans-serif;
  --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

/* Reset & Base */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-body);
  background-color: var(--bg);
  color: var(--text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  display: block;
}

ul, ol {
  list-style: none;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-headline);
  text-transform: uppercase;
  letter-spacing: 0.02em;
  line-height: 1.1;
  font-weight: 700;
}

h1 { font-size: clamp(2.5rem, 6vw, 4.5rem); }
h2 { font-size: clamp(2rem, 4vw, 3rem); }
h3 { font-size: clamp(1.25rem, 2.5vw, 1.75rem); }

p {
  color: var(--text-muted);
  font-size: 1rem;
  max-width: 65ch;
}

/* Utility */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

.section {
  padding: 5rem 0;
}

.section-title {
  text-align: center;
  margin-bottom: 3rem;
}

.section-title h2 {
  color: var(--text);
  margin-bottom: 0.75rem;
}

.section-title p {
  margin: 0 auto;
  font-size: 1.05rem;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.875rem 2rem;
  font-family: var(--font-headline);
  font-size: 1rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  border: 2px solid transparent;
  border-radius: 0;
  cursor: pointer;
  transition: all var(--transition);
}

.btn-primary {
  background: var(--red);
  color: var(--text);
  border-color: var(--red);
}

.btn-primary:hover {
  background: var(--red-dark);
  border-color: var(--red-dark);
  transform: translateY(-2px);
}

.btn-outline {
  background: transparent;
  color: var(--text);
  border-color: var(--text);
}

.btn-outline:hover {
  background: var(--text);
  color: var(--bg);
}

.btn-large {
  padding: 1rem 2.5rem;
  font-size: 1.15rem;
}

/* ============================================
   Top Bar
   ============================================ */
.top-bar {
  background: var(--red);
  color: var(--text);
  text-align: center;
  padding: 0.5rem 1rem;
  font-size: 0.85rem;
  font-weight: 600;
  letter-spacing: 0.03em;
}

.top-bar a {
  text-decoration: underline;
  margin-left: 0.5rem;
  font-weight: 700;
}

/* ============================================
   Navigation
   ============================================ */
.navbar {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(20, 20, 20, 0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
}

.navbar-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}

.logo {
  font-family: var(--font-headline);
  font-size: 1.5rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text);
}

.logo span {
  color: var(--red);
}

.nav-links {
  display: none;
  gap: 1.75rem;
}

.nav-links a {
  font-size: 0.85rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-muted);
  transition: color var(--transition);
  position: relative;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--text);
}

.nav-links a.active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 100%;
  height: 2px;
  background: var(--red);
}

.nav-utility {
  display: none;
  align-items: center;
  gap: 1rem;
}

.nav-utility a {
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-muted);
  transition: color var(--transition);
}

.nav-utility a:hover {
  color: var(--red);
}

.nav-utility .btn {
  padding: 0.5rem 1.25rem;
  font-size: 0.8rem;
}

.mobile-menu-btn {
  display: flex;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0.25rem;
}

.mobile-menu-btn span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--text);
  transition: all var(--transition);
}

.mobile-nav {
  display: none;
  position: absolute;
  top: 64px;
  left: 0;
  right: 0;
  background: var(--bg-elevated);
  border-bottom: 1px solid var(--border);
  padding: 1.5rem;
  flex-direction: column;
  gap: 1rem;
}

.mobile-nav.open {
  display: flex;
}

.mobile-nav a {
  font-size: 0.9rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-muted);
  padding: 0.5rem 0;
  border-bottom: 1px solid var(--border);
}

.mobile-nav a:hover {
  color: var(--text);
}

@media (min-width: 1024px) {
  .nav-links, .nav-utility {
    display: flex;
  }
  .mobile-menu-btn {
    display: none;
  }
  .mobile-nav.open {
    display: none;
  }
}

/* ============================================
   Hero
   ============================================ */
.hero {
  position: relative;
  min-height: 80vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, #1a0505 0%, #141414 50%, #0a0a0a 100%);
  z-index: 0;
}

.hero-bg::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 30% 50%, rgba(255,0,0,0.12) 0%, transparent 60%);
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 800px;
  padding: 2rem;
}

.hero h1 {
  color: var(--text);
  margin-bottom: 1.25rem;
}

.hero h1 span {
  color: var(--red);
}

.hero p {
  font-size: 1.15rem;
  color: var(--text-muted);
  margin-bottom: 2rem;
}

.hero-buttons {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  justify-content: center;
}

/* ============================================
   Community Promo
   ============================================ */
.community-promo {
  background: var(--bg-elevated);
  text-align: center;
}

.community-promo h2 {
  margin-bottom: 1rem;
}

.community-promo p {
  margin: 0 auto 1.75rem;
  font-size: 1.1rem;
}

/* ============================================
   Two Ways
   ============================================ */
.two-ways-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
}

.way-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  padding: 2.5rem;
  transition: all var(--transition);
}

.way-card:hover {
  border-color: var(--red);
  transform: translateY(-4px);
}

.way-card h3 {
  color: var(--red);
  margin-bottom: 0.75rem;
}

.way-card h4 {
  font-size: 1.5rem;
  margin-bottom: 1rem;
  color: var(--text);
}

.way-card p {
  margin-bottom: 1.5rem;
}

@media (min-width: 768px) {
  .two-ways-grid {
    grid-template-columns: 1fr 1fr;
  }
}

/* ============================================
   Studio Experience
   ============================================ */
.studio-experience {
  position: relative;
  background: linear-gradient(to bottom, var(--bg), #0f0f0f);
  text-align: center;
}

.studio-experience h2 {
  margin-bottom: 1rem;
}

.studio-experience p {
  margin: 0 auto 2rem;
  font-size: 1.1rem;
}

/* ============================================
   Free Trial CTA
   ============================================ */
.free-trial-cta {
  background: var(--red);
  text-align: center;
  padding: 4rem 0;
}

.free-trial-cta h2 {
  color: var(--text);
  margin-bottom: 1.5rem;
}

.free-trial-cta .btn-outline {
  border-color: var(--text);
  color: var(--text);
}

.free-trial-cta .btn-outline:hover {
  background: var(--text);
  color: var(--red);
}

/* ============================================
   Lifestyle Carousel
   ============================================ */
.carousel-section {
  background: var(--bg-elevated);
  overflow: hidden;
}

.carousel-wrapper {
  position: relative;
  max-width: 1000px;
  margin: 0 auto;
}

.carousel-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}

.carousel-slide {
  min-width: 100%;
  padding: 0 0.5rem;
}

.carousel-slide img {
  width: 100%;
  height: 400px;
  object-fit: cover;
  border-radius: 4px;
}

.carousel-nav {
  display: flex;
  justify-content: center;
  gap: 1rem;
  margin-top: 1.5rem;
}

.carousel-btn {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  border: 2px solid var(--text);
  background: transparent;
  color: var(--text);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all var(--transition);
  font-size: 1.25rem;
}

.carousel-btn:hover {
  background: var(--text);
  color: var(--bg);
}

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  margin-top: 1rem;
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  border: none;
  background: var(--border);
  cursor: pointer;
  transition: all var(--transition);
}

.carousel-dot.active {
  background: var(--red);
  transform: scale(1.2);
}

/* ============================================
   Newsletter
   ============================================ */
.newsletter {
  background: var(--bg);
  border-top: 1px solid var(--border);
  text-align: center;
}

.newsletter h3 {
  margin-bottom: 0.75rem;
}

.newsletter p {
  margin: 0 auto 1.5rem;
}

.newsletter-form {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  justify-content: center;
  max-width: 500px;
  margin: 0 auto;
}

.newsletter-form input {
  flex: 1 1 250px;
  padding: 0.875rem 1rem;
  background: var(--bg-card);
  border: 1px solid var(--border);
  color: var(--text);
  font-size: 1rem;
  outline: none;
  transition: border-color var(--transition);
}

.newsletter-form input:focus {
  border-color: var(--red);
}

.newsletter-form input::placeholder {
  color: #666;
}

.newsletter-message {
  margin-top: 1rem;
  font-size: 0.95rem;
  min-height: 1.5rem;
}

.newsletter-message.success {
  color: #4ade80;
}

.newsletter-message.error {
  color: var(--red);
}

/* ============================================
   Footer
   ============================================ */
.footer {
  background: #0a0a0a;
  border-top: 1px solid var(--border);
  padding: 4rem 0 2rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2.5rem;
  margin-bottom: 3rem;
}

.footer-col h4 {
  font-size: 1rem;
  margin-bottom: 1.25rem;
  color: var(--text);
}

.footer-col ul li {
  margin-bottom: 0.6rem;
}

.footer-col ul li a {
  color: var(--text-muted);
  font-size: 0.9rem;
  transition: color var(--transition);
}

.footer-col ul li a:hover {
  color: var(--red);
}

.country-select-wrapper {
  position: relative;
  display: inline-block;
}

.country-select-btn {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  background: var(--bg-card);
  border: 1px solid var(--border);
  color: var(--text);
  padding: 0.5rem 1rem;
  font-size: 0.9rem;
  cursor: pointer;
  transition: border-color var(--transition);
}

.country-select-btn:hover {
  border-color: var(--red);
}

.country-dropdown {
  display: none;
  position: absolute;
  bottom: 100%;
  left: 0;
  margin-bottom: 0.5rem;
  background: var(--bg-card);
  border: 1px solid var(--border);
  min-width: 180px;
  z-index: 100;
}

.country-dropdown.open {
  display: block;
}

.country-dropdown li {
  padding: 0.6rem 1rem;
  font-size: 0.9rem;
  color: var(--text-muted);
  cursor: pointer;
  transition: all var(--transition);
}

.country-dropdown li:hover {
  background: var(--bg-elevated);
  color: var(--text);
}

.footer-bottom {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  align-items: center;
  border-top: 1px solid var(--border);
  padding-top: 2rem;
}

.footer-bottom p {
  font-size: 0.8rem;
  color: #555;
}

@media (min-width: 768px) {
  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .footer-bottom {
    flex-direction: row;
    justify-content: space-between;
  }
}

@media (min-width: 1024px) {
  .footer-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}

/* ============================================
   Method Overview
   ============================================ */
.method-overview {
  background: var(--bg-elevated);
  text-align: center;
}

.method-overview p {
  margin: 0 auto;
  font-size: 1.1rem;
}

/* ============================================
   Weekly Schedule
   ============================================ */
.weekly-schedule {
  background: var(--bg);
}

.schedule-table-wrapper {
  overflow-x: auto;
}

.schedule-table {
  width: 100%;
  border-collapse: collapse;
  min-width: 600px;
}

.schedule-table th,
.schedule-table td {
  padding: 1.25rem 1.5rem;
  text-align: left;
  border-bottom: 1px solid var(--border);
}

.schedule-table th {
  font-family: var(--font-headline);
  font-size: 0.95rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-muted);
  background: var(--bg-card);
}

.schedule-table td {
  font-size: 1rem;
  color: var(--text);
}

.schedule-table tr:hover td {
  background: var(--bg-elevated);
}

.schedule-table td:first-child {
  font-weight: 600;
  color: var(--red);
}

/* ============================================
   Floor / Treadmill Toggle
   ============================================ */
.floor-treadmill {
  background: var(--bg-elevated);
}

.toggle-controls {
  display: flex;
  justify-content: center;
  gap: 0;
  margin-bottom: 2.5rem;
}

.toggle-btn {
  padding: 0.875rem 2.5rem;
  font-family: var(--font-headline);
  font-size: 1.1rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  background: transparent;
  border: 2px solid var(--border);
  color: var(--text-muted);
  cursor: pointer;
  transition: all var(--transition);
}

.toggle-btn:first-child {
  border-radius: 4px 0 0 4px;
}

.toggle-btn:last-child {
  border-radius: 0 4px 4px 0;
}

.toggle-btn.active {
  background: var(--red);
  border-color: var(--red);
  color: var(--text);
}

.toggle-btn:not(.active):hover {
  border-color: var(--text-muted);
  color: var(--text);
}

.toggle-content {
  max-width: 700px;
  margin: 0 auto;
  text-align: center;
}

.toggle-panel {
  display: none;
  animation: fadeIn 0.4s ease;
}

.toggle-panel.active {
  display: block;
}

.toggle-panel h3 {
  margin-bottom: 1rem;
  color: var(--red);
}

.toggle-panel p {
  font-size: 1.1rem;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ============================================
   CTA Book
   ============================================ */
.cta-book {
  background: linear-gradient(135deg, #1a0505, #141414);
  text-align: center;
  border-top: 1px solid var(--border);
}

.cta-book h2 {
  margin-bottom: 1.5rem;
}

/* ============================================
   Instructors
   ============================================ */
.instructors-hero {
  background: linear-gradient(135deg, #1a0505 0%, #141414 60%);
}

.filter-controls {
  display: flex;
  justify-content: center;
  margin-bottom: 2.5rem;
}

.filter-select {
  padding: 0.75rem 1.5rem;
  background: var(--bg-card);
  border: 1px solid var(--border);
  color: var(--text);
  font-size: 1rem;
  font-family: var(--font-body);
  cursor: pointer;
  outline: none;
  min-width: 220px;
  transition: border-color var(--transition);
}

.filter-select:focus {
  border-color: var(--red);
}

.instructor-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.5rem;
}

.instructor-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  padding: 2rem;
  text-align: center;
  transition: all var(--transition);
}

.instructor-card:hover {
  border-color: var(--red);
  transform: translateY(-4px);
}

.instructor-avatar {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--red), var(--red-dark));
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1.25rem;
  font-family: var(--font-headline);
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--text);
}

.instructor-card h4 {
  font-size: 1.25rem;
  margin-bottom: 0.25rem;
  color: var(--text);
}

.instructor-card .location {
  font-size: 0.9rem;
  color: var(--text-muted);
  margin-bottom: 1.25rem;
}

.instructor-card .book-link {
  font-family: var(--font-headline);
  font-size: 0.9rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--red);
  transition: color var(--transition);
}

.instructor-card .book-link:hover {
  color: var(--text);
}

@media (min-width: 640px) {
  .instructor-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .instructor-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}

/* ============================================
   FAQ Accordion
   ============================================ */
.faq-section {
  background: var(--bg);
}

.faq-list {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--border);
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.5rem 0;
  background: none;
  border: none;
  color: var(--text);
  font-family: var(--font-body);
  font-size: 1.05rem;
  font-weight: 600;
  text-align: left;
  cursor: pointer;
  transition: color var(--transition);
}

.faq-question:hover {
  color: var(--red);
}

.faq-icon {
  font-size: 1.5rem;
  font-weight: 300;
  line-height: 1;
  transition: transform var(--transition);
  flex-shrink: 0;
  margin-left: 1rem;
}

.faq-item.open .faq-icon {
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s cubic-bezier(0.4, 0, 0.2, 1), padding 0.4s ease;
}

.faq-item.open .faq-answer {
  max-height: 300px;
  padding-bottom: 1.5rem;
}

.faq-answer p {
  color: var(--text-muted);
  font-size: 0.95rem;
  line-height: 1.7;
}

/* ============================================
   Digital Platform
   ============================================ */
.features-overview {
  background: var(--bg-elevated);
}

.features-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
}

.feature-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  padding: 2rem;
  transition: all var(--transition);
}

.feature-card:hover {
  border-color: var(--red);
  transform: translateY(-4px);
}

.feature-card h3 {
  color: var(--red);
  margin-bottom: 0.75rem;
  font-size: 1.15rem;
}

.feature-card p {
  font-size: 0.95rem;
}

@media (min-width: 768px) {
  .features-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .features-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.workout-types {
  background: var(--bg);
  text-align: center;
}

.workout-types-grid {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 1rem;
  margin-top: 2rem;
}

.workout-tag {
  padding: 0.75rem 1.5rem;
  background: var(--bg-card);
