   RedRoom Fitness — Global Scripts
   ============================================ */

document.addEventListener('DOMContentLoaded', () => {
  initMobileNav();
  initCarousel();
  initNewsletter();
  initCountrySelect();
  initWorkoutToggle();
  initInstructorFilter();
